#include <iostream>
#include <string>
#include <vector>
#include <sstream>

static bool match(const std::string &a, const std::string &b) {
    return a[0] == b[0] || a[1] == b[1];
}

void solve(std::istream &inf, std::ostream &ouf) {
    std::string s;
    std::getline(inf, s);

    std::string line;
    std::getline(inf, line);

    std::vector<std::string> tokens;
    std::string cur;
    std::istringstream iss(line);
    while (std::getline(iss, cur, ' ')) {
        tokens.push_back(cur);
    }

    bool found = false;
    for (const std::string &t : tokens) {
        if (match(s, t)) {
            found = true;
            break;
        }
    }

    ouf << (found ? "YES" : "NO") << std::endl;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve(std::cin, std::cout);
    return 0;
}
